O=Path('outputs/pisco_fish_effort_20261101')
e=pd.read_csv(O/'effects.csv');p=pd.read_csv(O/'pooled.csv');d=pd.read_csv(O/'paired_values.csv');flags=pd.read_csv(O/'affected_site_years.csv')
j=e[e.arm.eq('Before')].merge(e[e.arm.eq('After')],on=['contrast','series_id','metric'],suffixes=('_before','_after'),validate='one_to_one');j['estimate_change']=j.estimate_after-j.estimate_before
