base=d[d.scenario.eq('Legacy')][['series_id','year','lnDiff']];delta=d.merge(base,on=['series_id','year'],suffixes=('','_legacy'));delta['ratio_change']=delta.lnDiff-delta.lnDiff_legacy;delta.to_csv(O/'annual_changes.csv',index=False)
