summary=[]
for sid,g in flags.groupby('series_id'):
 z=j[j.series_id.eq(sid)];a=delta[delta.series_id.eq(sid)&delta.scenario.eq('Visit_mean')&delta.complete_support]
 summary.append(dict(series_id=sid,MPA=g.MPA.iloc[0],Resp=g.Resp.iloc[0],in_current_manuscript=membership.get(sid,False),repeat_site_years=int(g.revisited_units.gt(0).sum()),unequal_level_site_years=int(g.unequal_levels.sum()),nonstandard_site_years=int(g.nonstandard_units.gt(0).sum()),annual_repeat_changes=';'.join(map(str,a.loc[a.ratio_change.abs()>1e-8,'year'])),repeat_changes_fitted_recovery=bool(((z.contrast=='Repeat_visits')&(z.metric=='Post_slope')&(z.estimate_change.abs()>1e-8)).any()),complete_level_changes_fitted_recovery=bool(((z.contrast=='Complete_levels')&(z.metric=='Post_slope')&(z.estimate_change.abs()>1e-8)).any())))
s=pd.DataFrame(summary);s.to_csv(O/'comparison_summary.csv',index=False)
