for ax,resp,label in zip(axs,['Bio','Den'],['Biomass','Density']):
 z=j[(j.contrast=='Strict_MID_footprint')&(j.metric=='Post_slope')&(j.Source_before=='PISCO')&(j.Resp_before==resp)].sort_values('MPA_before')
 yy=np.arange(len(z));ax.hlines(yy,z.estimate_before,z.estimate_after,color='#bbbbbb');ax.scatter(z.estimate_before,yy,facecolors='white',edgecolors='#777777',s=25);ax.scatter(z.estimate_after,yy,color='#b96431',s=25);ax.axvline(0,color='#dddddd');ax.set_yticks(yy,z.MPA_before.map(lambda n:n if n.startswith('Point Dume') else n.replace(' SMCA','').replace(' SMR','')));ax.set_xlabel('Annual change in log protected/reference ratio');ax.text(.97,.97,label,ha='right',va='top',transform=ax.transAxes);ax.spines[['top','right']].set_visible(False)
